/* ============ 纯函数（可测试，无副作用） ============ */
var PF = (function(){
  function extractVars(tpl){
    var re = /\{\{\s*([\w]+)\s*\}\}/g, m, set = {};
    while((m = re.exec(tpl)) !== null){ set[m[1]] = 1; }
    return Object.keys(set).sort();
  }
  function fillTemplate(tpl, map){
    map = map || {};
    return tpl.replace(/\{\{\s*([\w]+)\s*\}\}/g, function(_, name){
      return (map[name] !== undefined && map[name] !== "") ? map[name] : ("{{"+name+"}}");
    });
  }
  function estTokens(s){
    if(!s) return 0;
    return Math.max(1, Math.ceil(Array.from(s).length / 4));
  }
  function estCost(model, inT, outT){
    var table = {
      "gpt-4o":      [0.005, 0.015],
      "gpt-4o-mini": [0.00015, 0.0006],
      "gpt-3.5-turbo":[0.0005, 0.0015],
      "claude-3-5-sonnet":[0.003, 0.015],
      "claude-3-haiku":[0.00025,0.00125],
      "default":      [0.001, 0.002]
    };
    var p = table[model] || table["default"];
    return (inT/1000)*p[0] + (outT/1000)*p[1];
  }
  function maskKey(k){
    if(!k) return "";
    if(k.length <= 7) return "••••";
    return k.slice(0,3) + "…" + k.slice(-4);
  }
  return { extractVars:extractVars, fillTemplate:fillTemplate, estTokens:estTokens, estCost:estCost, maskKey:maskKey };
})();

if(typeof module !== "undefined" && module.exports){ module.exports = PF; }
if(typeof window !== "undefined"){ window.PromptForgePure = PF; }
